      $jsonBody,
      [System.Text.Encoding]::UTF8,
      'application/json'
    )
  }

  try {
    $response = $client.Send($request)
    $text = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
    [pscustomobject]@{
      Status = [int]$response.StatusCode
      Text = $text
      Location = if ($null -ne $response.Headers.Location) {
        $response.Headers.Location.ToString()
      } else {
        $null
      }
      RequestId = if ($response.Headers.Contains('X-GitHub-Request-Id')) {
        ($response.Headers.GetValues('X-GitHub-Request-Id') | Select-Object -First 1)
      } else {
        $null
      }
    }
  } finally {
    $request.Dispose()
    if ($null -ne $response) {
      $response.Dispose()
    }
  }
