        Reason = $property.Value.reason
      })
    }
  }

  $retryMap = @{}
  foreach ($record in @($records)) {
    if ($record.Status -ne 'unknown' -or $record.InputPurl -notmatch '(?i)[?&]repository_url=') {
      continue
    }
    $stripped = $record.InputPurl -replace '(?i)([?&])repository_url=[^&]*&?', '$1'
    $stripped = $stripped.TrimEnd('?', '&') -replace '\?&', '?'
    if ($stripped -ne $record.InputPurl) {
      if (-not $retryMap.ContainsKey($stripped)) {
        $retryMap[$stripped] = [System.Collections.Generic.List[string]]::new()
      }
      $retryMap[$stripped].Add($record.InputPurl)
    }
  }

  $retryPurls = @($retryMap.Keys | Sort-Object)
  foreach ($batch in (Split-Batches -Items $retryPurls -Size 40)) {
    $response = Invoke-GitHubApi -Method POST -Uri "/repos/$Owner/$Repo/license-compliance/package-checks" -Body @{ purls = @($batch) }
    if ($response.Status -ne 200) {
      $errors.Add([pscustomobject]@{
        Status = $response.Status
        Error = $response.Text
        RequestId = $response.RequestId
        Purls = @($batch)
        QualifierRetry = $true
      })
      continue
    }
    $json = Convert-ResponseJson -Response $response
    foreach ($property in $json.purls.PSObject.Properties) {
      foreach ($original in @($retryMap[$property.Name])) {
        $records.Add([pscustomobject]@{
          InputPurl = $original
          CheckedPurl = $property.Name
          QualifierRetry = $true
          Status = $property.Value.status
          License = $property.Value.license
          Reason = $property.Value.reason
        })
      }
    }
  }

  [pscustomobject]@{
    Records = @($records)
    Errors = @($errors)
  }
}

$fleet = Get-Content -LiteralPath $FleetPath -Raw | ConvertFrom-Json -Depth 100
$repositories = @($fleet.data.organization.repositories.nodes) + @($fleet.data.personal)
$policyResponse = Invoke-GitHubApi -Method GET -Uri '/enterprises/lcv-ideas-software/license-compliance/policies/default'
$policyRecord = [pscustomobject]@{
  Status = $policyResponse.Status
  RequestId = $policyResponse.RequestId
  Body = if ($policyResponse.Status -eq 200) {
    Convert-ResponseJson -Response $policyResponse
  } else {
