}
$policyRecord | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath (Join-Path $OutputDir 'enterprise-license-policy.json') -Encoding utf8NoBOM

$inventory = [System.Collections.Generic.List[object]]::new()
foreach ($repository in $repositories) {
  $owner, $repo = $repository.nameWithOwner -split '/', 2
  $safeName = "$owner--$repo"
  Write-Host "Collecting $($repository.nameWithOwner)"

  $ownRulesets = Get-PagedArray -Path "/repos/$owner/$repo/rulesets?includes_parents=false"
  $effectiveRulesets = Get-PagedArray -Path "/repos/$owner/$repo/rulesets?includes_parents=true"
  $branchRules = Get-PagedArray -Path "/repos/$owner/$repo/rules/branches/$($repository.defaultBranchRef.name)"

  $actionsPermissionsResponse = Invoke-GitHubApi -Method GET -Uri "/repos/$owner/$repo/actions/permissions"
  $actionsPermissions = [pscustomobject]@{
    Status = $actionsPermissionsResponse.Status
