      Convert-ResponseJson -Response $actionsPermissionsResponse
    } else {
      $null
    }
    Error = if ($actionsPermissionsResponse.Status -eq 200) { $null } else { $actionsPermissionsResponse.Text }
  }

  $selectedActionsResponse = Invoke-GitHubApi -Method GET -Uri "/repos/$owner/$repo/actions/permissions/selected-actions"
  $selectedActions = [pscustomobject]@{
    Status = $selectedActionsResponse.Status
    RequestId = $selectedActionsResponse.RequestId
    Body = if ($selectedActionsResponse.Status -eq 200) {
      Convert-ResponseJson -Response $selectedActionsResponse
    } else {
      $null
    }
    Error = if ($selectedActionsResponse.Status -eq 200) { $null } else { $selectedActionsResponse.Text }
  }

  $codeScanning = Get-PagedArray -Path "/repos/$owner/$repo/code-scanning/alerts?state=open"
  $dependabot = Get-PagedArray -Path "/repos/$owner/$repo/dependabot/alerts?state=open"
  $secretScanning = Get-PagedArray -Path "/repos/$owner/$repo/secret-scanning/alerts?state=open"
  $encodedWindow = [Uri]::EscapeDataString("$WindowStartUtc..$WindowEndUtc")
  $workflowRuns = Get-PagedWrapped -Path "/repos/$owner/$repo/actions/runs?created=$encodedWindow" -Property 'workflow_runs'

  $sbomPath = Join-Path $sbomDir "$safeName.json"
  $sbomResult = Get-Sbom -Owner $owner -Repo $repo -Destination $sbomPath
  $sbomSummary = $null
