    $sbom = Get-Content -LiteralPath $sbomPath -Raw | ConvertFrom-Json -Depth 100
    $packages = @($sbom.sbom.packages)
    $purlSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($package in $packages) {
      foreach ($externalRef in @($package.externalRefs)) {
        if ($externalRef.referenceType -eq 'purl' -and -not [string]::IsNullOrWhiteSpace($externalRef.referenceLocator)) {
          [void]$purlSet.Add([string]$externalRef.referenceLocator)
        }
      }
    }
    $purls = @($purlSet | Sort-Object)
    $checks = Invoke-PurlChecks -Owner $owner -Repo $repo -Purls $purls
    $checksPath = Join-Path $checksDir "$safeName.json"
    $checks | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $checksPath -Encoding utf8NoBOM

    $originalRecords = @($checks.Records | Where-Object { -not $_.QualifierRetry })
    $retryRecords = @($checks.Records | Where-Object QualifierRetry)
    $licenseSummary = [pscustomobject]@{
      Purls = $purls.Count
      OriginalResults = $originalRecords.Count
      Allowed = @($originalRecords | Where-Object Status -eq 'allowed').Count
      Denied = @($originalRecords | Where-Object Status -eq 'denied').Count
      Unknown = @($originalRecords | Where-Object Status -eq 'unknown').Count
      Other = @($originalRecords | Where-Object { $_.Status -notin @('allowed', 'denied', 'unknown') }).Count
      QualifierRetryResults = $retryRecords.Count
      QualifierRetryAllowed = @($retryRecords | Where-Object Status -eq 'allowed').Count
      Errors = @($checks.Errors).Count
      ChecksFile = $checksPath
      ChecksSha256 = (Get-FileHash -LiteralPath $checksPath -Algorithm SHA256).Hash
    }
    $sbomSummary = [pscustomobject]@{
      Packages = $packages.Count
      Purls = $purls.Count
      File = $sbomPath
      Sha256 = (Get-FileHash -LiteralPath $sbomPath -Algorithm SHA256).Hash
      Created = $sbom.sbom.creationInfo.created
      Namespace = $sbom.sbom.documentNamespace
      Generation = $sbomResult
    }
  }

  $inventory.Add([pscustomobject]@{
    Repository = $repository.nameWithOwner
    RepositoryId = $repository.id
    Visibility = $repository.visibility
    DefaultBranch = $repository.defaultBranchRef.name
    HeadSha = $repository.defaultBranchRef.target.oid
    HeadSignature = $repository.defaultBranchRef.target.signature
    OwnRulesets = $ownRulesets
    EffectiveRulesets = $effectiveRulesets
    DefaultBranchRules = $branchRules
    ActionsPermissions = $actionsPermissions
    SelectedActions = $selectedActions
    OpenCodeScanning = $codeScanning
    OpenDependabot = $dependabot
    OpenSecretScanning = $secretScanning
    WorkflowRunsInWindow = $workflowRuns
    Sbom = $sbomSummary
    SbomError = if ($sbomResult.Success) { $null } else { $sbomResult }
    License = $licenseSummary
  })
}

$result = [pscustomobject]@{
