const sid = load("op_session_id");
const repos = [".github-org",".github-private","admin-app","astrologo-android","astrologo-app","astrologo-ios","calculadora-android","calculadora-app","calculadora-ios","cross-review","github-operations","maestro-android","maestro-app","maestro-ios","mainsite-app","mtasts-motor","oraculo-financeiro","programa-android","programa-ios","sponsor-motor","ultrabrain-mcp","lcv-leo"];
const arr = repos.map(r=>`'${r}'`).join(",");
const cmd = `$roots=@(${arr});$base='C:\\Users\\lcvle\\lcv-workspace';$rows=foreach($r in $roots){$p=Join-Path $base $r;git -C $p fetch origin "+refs/heads/main:refs/remotes/origin/main" --quiet;if($LASTEXITCODE -ne 0){throw "fetch failed: $r"};$dirty=@(git -C $p status --porcelain --untracked-files=no);[pscustomobject]@{repo=$r;originMain=(git -C $p rev-parse refs/remotes/origin/main);localHead=(git -C $p rev-parse HEAD);branch=(git -C $p branch --show-current);trackedDirtyCount=$dirty.Count}};$rows|ConvertTo-Json -Compress\r`;
const r = await tools.write_stdin({session_id:sid, chars:cmd, yield_time_ms:30000, max_output_tokens:20000});
text(r.output);

