function waitForReady(child, marker, timeoutMs = 5_000) {
  return new Promise((resolve, reject) => {
    let stdout = "";
    let stderr = "";
    let settled = false;
    const timeout = setTimeout(() => {
      fail(new Error(`holder nao publicou ${marker} em ${timeoutMs}ms`));
    }, timeoutMs);

    const cleanup = () => {
      clearTimeout(timeout);
      child.stdout.off("data", onStdout);
      child.stderr.off("data", onStderr);
      child.off("error", onError);
      child.off("exit", onExit);
    };
    const fail = (error) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };
    const onStdout = (chunk) => {
      stdout += chunk.toString("utf8");
      const completeLines = stdout.split(/\r?\n/u).slice(0, -1);
      if (!completeLines.includes(marker) || settled) return;
      settled = true;
      cleanup();
      resolve();
    };
    const onStderr = (chunk) => {
      stderr += chunk.toString("utf8");
    };
    const onError = (error) => {
      fail(new Error(`holder encontrou erro antes de ${marker}: ${error.message}`));
    };
    const onExit = (code, signal) => {
      fail(
        new Error(
          `holder saiu antes de ${marker}: code=${code} signal=${signal} stderr=${stderr.trim()}`,
        ),
      );
    };

    child.stdout.on("data", onStdout);
    child.stderr.on("data", onStderr);
    child.once("error", onError);
    child.once("exit", onExit);
  });
}

